@testset "Two independent random-intercept SD priors" begin
    form = bf(@formula(y ~ x + (1 | site) + (1 | observer)), @formula(sigma ~ x))
    ps = drm_prior_sd_gamma(dpar="mu", group="site", shape=2., rate=3.)
    po = drm_prior_sd_gamma(dpar="mu", group="observer", shape=3.5, rate=1.7)
    fm = drm_prior_normal(dpar="mu", coef="(Intercept)", mean=.25, sd=1.4)
    fs = drm_prior_normal(dpar="sigma", coef="x", mean=-.1, sd=.7)
    cases = Dict("none"=>drm_priors(), "site"=>drm_priors(ps),
                 "observer"=>drm_priors(po), "both"=>drm_priors(ps,po),
                 "mixed"=>drm_priors(fm,fs,ps,po))
    dat(k) = (y=OR2_Y[k], x=OR2_X, site=OR2_SITE, observer=OR2_OBSERVER)
    fits = Dict()
    for key in keys(OR2_Y), c in keys(cases)
        fits[(key,c)] = drm(form, Gaussian(); data=dat(key), priors=cases[c])
    end
    for (key, c, q, obj, grad, hess) in OR2_RECORDS
        fit = fits[(key,c)]
        @test abs(fit.nll(q)-obj) <= 1e-8*max(1,abs(obj))
        @test maximum(abs.(ForwardDiff.gradient(fit.nll,q) .- grad)) <= 1e-6
        g = zeros(length(q)); fit.nllgrad(g,q)
        @test maximum(abs.(g .- grad)) <= 1e-6
        @test all(abs.(ForwardDiff.hessian(fit.nll,q) .- hess) .<= 1e-5 .* max.(1,abs.(hess)))
    end
    for (key,c,theta,obj,_,floor,eig) in OR2_FITS
        floor && continue
        fit=fits[(key,c)]
        @test abs(fit.nll(fit.theta)-obj) <= 1e-6*max(1,abs(obj))
        @test maximum(abs,ForwardDiff.gradient(fit.nll,fit.theta)) <= 1e-5
        eig > .01 && @test fit.theta ≈ theta atol=1e-5
    end
    fit=fits[("0.6","mixed")]
    @test fit.estim_method == :MAP
    @test fit.loglik ≈ -fit.penalty.data_nll(fit.theta) atol=1e-9
    @test fit.nll(fit.theta) ≈ -fit.loglik + fit.penalty.fixed_penalty + fit.penalty.sd_penalty atol=1e-9
    @test length(fit.penalty.sd_rows) == 2
    @test update(fit, form; data=dat("0.6")).theta ≈ fit.theta atol=1e-6
    @test_throws ArgumentError confint(fit)
    @test_throws ArgumentError aic(fit)
    @test_throws ArgumentError drm(form,Gaussian();data=dat("0.6"),priors=drm_priors(ps,ps))
    @test_throws ArgumentError drm(form,Gaussian();data=dat("0.6"),priors=drm_priors(drm_prior_sd_gamma(dpar="mu",group="missing",shape=2.,rate=3.)))
    @test_throws ArgumentError drm(form,Gaussian();data=dat("0.6"),priors=cases["both"],method=:REML)
    @test_throws ArgumentError drm(form,Gaussian();data=dat("0.6"),priors=cases["both"],weights=fill(2.,12))
    reverseform = bf(@formula(y ~ x + (1 | observer) + (1 | site)), @formula(sigma ~ x))
    reversefit = drm(reverseform,Gaussian();data=dat("0.6"),priors=cases["both"])
    @test reversefit.nll(reversefit.theta) ≈ fits[("0.6","both")].nll(fits[("0.6","both")].theta) atol=1e-7
    @test Dict(r.group=>r.index for r in resolve_priors(reverseform,Gaussian();data=dat("0.6"),priors=cases["both"])) == Dict("site"=>6,"observer"=>5)
end

