@testset "Asymmetric two-intercept oracle" begin
    form = bf(@formula(y ~ x + (1 | site) + (1 | observer)), @formula(sigma ~ x))
    ps = drm_prior_sd_gamma(dpar="mu", group="site", shape=2., rate=3.)
    po = drm_prior_sd_gamma(dpar="mu", group="observer", shape=3.5, rate=1.7)
    fm = drm_prior_normal(dpar="mu", coef="(Intercept)", mean=.25, sd=1.4)
    fs = drm_prior_normal(dpar="sigma", coef="x", mean=-.1, sd=.7)
    cases = Dict("none"=>drm_priors(), "site"=>drm_priors(ps), "observer"=>drm_priors(po),
                 "both"=>drm_priors(ps,po), "mixed"=>drm_priors(fm,fs,ps,po))
    dat(k)=(y=OR2_ASYM_Y[k],x=OR2_X,site=OR2_SITE,observer=OR2_OBSERVER)
    fits=Dict((k,c)=>drm(form,Gaussian();data=dat(k),priors=cases[c]) for k in keys(OR2_ASYM_Y), c in keys(cases))
    for (key,c,q,obj,grad,hess) in OR2_ASYM_POINTS
        fit=fits[(key,c)]
        @test abs(fit.nll(q)-obj) <= 1e-8*max(1,abs(obj))
        @test maximum(abs.(ForwardDiff.gradient(fit.nll,q).-grad)) <= 1e-6
        g=zeros(length(q)); fit.nllgrad(g,q)
        @test maximum(abs.(g.-grad)) <= 1e-6
        @test all(abs.(ForwardDiff.hessian(fit.nll,q).-hess) .<= 1e-5 .* max.(1,abs.(hess)))
    end
    for (key,c,theta,obj,_,floor,eig) in OR2_ASYM_FITS
        floor && continue
        fit=fits[(key,c)]
        @test abs(fit.nll(fit.theta)-obj) <= 1e-6*max(1,abs(obj))
        @test maximum(abs,ForwardDiff.gradient(fit.nll,fit.theta)) <= 1e-5
        eig > .01 && @test fit.theta ≈ theta atol=1e-5
    end
end

@testset "Two-intercept bridge v3" begin
    data=(y=OR2_Y["0.6"],x=OR2_X,site=OR2_SITE,observer=OR2_OBSERVER)
    form=Dict("mu"=>"y ~ x + (1 | site) + (1 | observer)","sigma"=>"sigma ~ x")
    spec(group,a,b)=Dict("kind"=>"ranef_sd_gamma","dpar"=>"mu","group"=>group,"coef"=>"(Intercept)","block_kind"=>"iid_random_intercept","shape"=>a,"rate"=>b,"measure"=>"natural_sd")
    s=spec("site",2.,3.); o=spec("observer",3.5,1.7)
    row(s,i)=merge(s,Dict("spec_index"=>i,"class"=>"ranef_sd"))
    opts(ss)=Dict("prior_contract"=>"parameter_priors_v3","priors_v3"=>ss,"prior_expected_v3"=>[row(p,i) for (i,p) in enumerate(ss)])
    for ss in ([s],[o],[s,o],[o,s])
        out=DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=opts(ss))
        @test out["prior_contract"] == "parameter_priors_v3"
        @test eltype(out["sd_prior_contributions"]) === Any
        @test out["working_coordinates"][end-1:end] == ["eta_sd[mu|site|(Intercept)]","eta_sd[mu|observer|(Intercept)]"]
        @test [x["group"] for x in out["sd_prior_contributions"]] == [x["group"] for x in ss]
        @test out["sd_prior_penalty"] ≈ sum(x["penalty"] for x in out["sd_prior_contributions"])
        @test out["penalized_objective"] ≈ out["data_nll"] + out["fixed_prior_penalty"] + out["sd_prior_penalty"]
        @test out["penalized_gradient"] ≈ out["data_gradient"] + out["fixed_prior_gradient"] + out["sd_prior_gradient"]
    end
    bad=opts([s,o]); bad["prior_expected_v3"][1]["rate"]=4.
    @test_throws ArgumentError DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=bad)
    for (key,value) in (("group","observer"),("coef","x"),("block_kind","correlated"),
                        ("measure","log_sd"),("shape",9.),("spec_index",2))
        bad=opts([s,o]); bad["prior_expected_v3"][1][key]=value
        @test_throws ArgumentError DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=bad)
    end
    bad=opts([s,o]); pop!(bad["prior_expected_v3"])
    @test_throws ArgumentError DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=bad)
    bad=opts([s,o]); push!(bad["prior_expected_v3"],bad["prior_expected_v3"][2])
    @test_throws ArgumentError DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=bad)
    @test_throws ArgumentError DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=opts([s,s]))
    @test_throws ArgumentError DRModels.drm_bridge(;formula=Dict("mu"=>"y ~ x + (1 | site)","sigma"=>"sigma ~ x"),family="gaussian",data=data,options=opts([s]))
    @test_throws ArgumentError DRModels._bridge_prior_contract(Dict(:prior_contract=>"parameter_priors_v3",:priors_v3=>[s]))
    @test_throws ArgumentError DRModels._bridge_prior_contract(Dict(:prior_contract=>"parameter_priors_v3",:priors_v3=>[s],:prior_expected_v3=>[row(s,1)],:priors_v2=>[s]))
    v2=Dict("prior_contract"=>"parameter_priors_v2","priors_v2"=>[s],"prior_expected_v2"=>[row(s,1)])
    @test_throws ArgumentError DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=v2)
    v1=Dict("priors"=>[Dict("kind"=>"normal","dpar"=>"mu","coef"=>"x","mean"=>0.,"sd"=>2.)],
            "prior_expected"=>[Dict("dpar"=>"mu","coef"=>"x")])
    v1fit=DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=v1)
    @test v1fit["fixed_prior_contract"] == "fixed_effect_priors_v1"
    @test !haskey(v1fit,"prior_contract")
    fn=Dict("kind"=>"fixed_normal","dpar"=>"mu","coef"=>"x","mean"=>0.,"sd"=>2.)
    fr=merge(fn,Dict("spec_index"=>2,"class"=>"fixed"))
    mixed=Dict("prior_contract"=>"parameter_priors_v3","priors_v3"=>[s,fn],"prior_expected_v3"=>[row(s,1),fr])
    mixedfit=DRModels.drm_bridge(;formula=form,family="gaussian",data=data,options=mixed)
    @test mixedfit["fixed_prior_penalty"] > 0
    @test mixedfit["penalized_gradient"] ≈ mixedfit["data_gradient"] + mixedfit["fixed_prior_gradient"] + mixedfit["sd_prior_gradient"]
    native, dat, labels=DRModels._bridge_formula(form,"gaussian",DRModels._bridge_data(data);labels=true)
    fit=drm(native,Gaussian();data=dat,priors=drm_priors(drm_prior_sd_gamma(dpar="mu",group="site",shape=2.,rate=3.)))
    rec=[row(s,1)]
    changed=deepcopy(rec); changed[1]["group"]="observer"
    @test_throws ArgumentError DRModels._bridge_attach_priors_v3!(Dict{String,Any}(),fit,changed,labels)
    saved=fit.penalty.sd_rows[1]
    fit.penalty.sd_rows[1]=merge(saved,(index=6,))
    @test_throws ArgumentError DRModels._bridge_attach_priors_v3!(Dict{String,Any}(),fit,rec,labels)
    fit.penalty.sd_rows[1]=saved
end

@testset "Two-intercept prior guards and unit scaling" begin
    d=(y=OR2_Y["0.6"],x=OR2_X,site=OR2_SITE,observer=OR2_OBSERVER)
    form=bf(@formula(y ~ x + (1 | site) + (1 | observer)), @formula(sigma ~ x))
    ps=drm_prior_sd_gamma(dpar="mu",group="site",shape=2.,rate=3.)
    po=drm_prior_sd_gamma(dpar="mu",group="observer",shape=3.5,rate=1.7)
    fixed=drm_priors(drm_prior_normal(dpar="mu",coef="x",mean=.1,sd=2.))
    ff=drm(form,Gaussian();data=d,priors=fixed)
    @test ff.estim_method === :MAP
    g=zeros(length(ff.theta)); ff.nllgrad(g,ff.theta)
    @test g ≈ ForwardDiff.gradient(ff.nll,ff.theta) atol=1e-6
    @test update(ff,form;data=d).theta ≈ ff.theta atol=1e-6
    f=drm(form,Gaussian();data=d,priors=drm_priors(ps,po))
    @test_throws ArgumentError DRModels._bootstrap_refit_kwargs(f)
    rows=f.penalty.sd_rows
    @test all(r -> DRModels._sd_prior_interior(f.theta[r.index]) && abs(f.theta[r.index]) < 30, rows)
    @test !DRModels._multi_sd_prior_converged(true,fill(1e-3,6),f.theta,rows)
    @test !DRModels._multi_sd_prior_converged(true,zeros(6),[f.theta[1:4]; -30.; f.theta[6]],rows)
    @test !DRModels._multi_sd_prior_converged(true,fill(NaN,6),f.theta,rows)
    q=[.6,.3,-.4,.1,-1.2,-.3]
    actual=f.nll(q); base=f.penalty.data_nll(q)
    values=[DRModels._sd_prior_value(r,q) for r in rows]
    @test abs(actual - (base+values[1])) > 1e-6
    @test abs(actual - (base+2sum(values))) > 1e-6
    @test abs(actual - (base+sum(values)-q[5]-q[6])) > 1e-6
    @test abs(actual - (base+3sum(values))) > 1e-6
    unnormalized=sum(r.rate*exp(q[r.index])-(r.shape-1)*q[r.index] for r in rows)
    @test abs(actual-(base+unnormalized)) > 1e-6
    swapped_shape_rate=sum(r.shape*exp(q[r.index])-(r.rate-1)*q[r.index] - r.rate*log(r.shape)+DRModels.loggamma(r.rate) for r in rows)
    @test abs(actual-(base+swapped_shape_rate)) > 1e-6
    swapped=[q[1:4]; q[6]; q[5]]
    @test abs(actual - (base+sum(DRModels._sd_prior_value(r,swapped) for r in rows))) > 1e-6
    unpen=drm(form,Gaussian();data=d)
    emptyfit=drm(form,Gaussian();data=d,priors=drm_priors())
    @test unpen.nll(q) ≈ emptyfit.nll(q) atol=1e-10
    @test unpen.theta ≈ emptyfit.theta atol=1e-8
    c=3.7
    dc=merge(d,(y=c.*d.y,))
    pc=drm_priors(drm_prior_sd_gamma(dpar="mu",group="site",shape=2.,rate=3/c),
                  drm_prior_sd_gamma(dpar="mu",group="observer",shape=3.5,rate=1.7/c))
    fc=drm(form,Gaussian();data=dc,priors=pc)
    qc=[c*q[1],c*q[2],q[3]+log(c),q[4],q[5]+log(c),q[6]+log(c)]
    @test fc.nll(qc) ≈ actual+(length(d.y)+2)*log(c) atol=1e-8
end
